profiles={}
def profile(name,url,label_de,label_en,summary_de,summary_en,focus_de,focus_en,roles_de,roles_en,sources,aliases=None):
 profiles[name]=dict(officialUrl=url,officialLabel=dict(de=label_de,en=label_en),metaDescription=dict(de=summary_de.split('. ')[0]+'.',en=summary_en.split('. ')[0]+'.'),summary=dict(de=summary_de,en=summary_en),focus=dict(de=focus_de,en=focus_en),buyerGroups=dict(de=roles_de,en=roles_en),officialSources=[dict(url=u,label=dict(de=d,en=e)) for u,d,e in sources],languageNote=dict(de='Verknüpfte Beiträge zeigen belegte Produkt-, Integrations- oder Geschäftsbezüge. Die Leistungen des ursprünglichen Anbieters und die Verfügbarkeit einzelner Angebote bleiben getrennt zu prüfen. Die Prüfung des Unternehmensbezugs ändert nicht automatisch den vollständigen Prüfstatus eines Wissensobjekts.',en='Linked articles show documented product, integration or business relationships. The original provider’s services and individual offer availability require separate assessment. Reviewing the company relationship does not automatically change the full review status of a knowledge item.'))
 if aliases:profiles[name]['aliases']=aliases
profile('Microsoft','https://www.microsoft.com/en-us/about','Microsoft: Unternehmens- und Produktquellen','Microsoft: company and product sources',
'Microsoft entwickelt Cloud-Plattformen, Unternehmenssoftware und Sicherheitslösungen. Azure adressiert Compute, Daten, Anwendungen und KI; Microsoft 365 verbindet Produktivität und Zusammenarbeit. Dynamics 365 unterstützt CRM- und ERP-Prozesse, Power Platform die Entwicklung und Automatisierung von Anwendungen. Entra steuert Identitäten und Zugriffe, Purview Daten-Governance und Compliance; Copilot ergänzt KI-Funktionen in unterschiedlichen Produkten. Für Unternehmen zählen vorhandene Lizenzen, Mandantenstruktur, Datenstandorte, Berechtigungen, Integration und Betriebsverantwortung. Partner ergänzen das Portfolio mit Backup, Governance, Hardware, Konnektoren und Umsetzung. Veeam- oder Druva-Angebote für Microsoft 365 sind deshalb Angebote dieser Anbieter; eine Azure-basierte Anwendung bleibt das Produkt ihres Herstellers. Die verlinkten Artikel unterscheiden Plattformnutzung, technische Integration und konkrete Kooperationen. Eine Nennung von Microsoft begründet weder eine Zertifizierung noch den Status eines Umsetzungspartners.',
'Microsoft develops cloud platforms, enterprise software and security solutions. Azure addresses compute, data, applications and AI; Microsoft 365 combines productivity and collaboration. Dynamics 365 supports CRM and ERP processes, while Power Platform enables application development and automation. Entra governs identities and access, Purview data governance and compliance; Copilot adds AI capabilities across distinct products. Businesses should assess existing licenses, tenant structures, data locations, permissions, integration and operational ownership. Partners complement the portfolio with backup, governance, hardware, connectors and implementation. Veeam or Druva offerings for Microsoft 365 therefore remain those vendors’ products; an Azure-based application remains its manufacturer’s product. Linked articles distinguish platform use, technical integration and specific collaboration. Mentioning Microsoft establishes neither certification nor implementation-partner status.',
['Azure und hybride Infrastruktur','Microsoft 365 und Zusammenarbeit','Dynamics 365: CRM und ERP','Power Platform und Automatisierung','Entra: Identität und Zugriff','Purview: Daten-Governance','Copilot und KI-Anwendungen','Partnerlösungen für Backup und Integration'],['Azure and hybrid infrastructure','Microsoft 365 and collaboration','Dynamics 365: CRM and ERP','Power Platform and automation','Entra: identity and access','Purview: data governance','Copilot and AI applications','Partner solutions for backup and integration'],
['CIO, CTO und IT-Leitung','Cloud- und Enterprise-Architektur','Workplace- und Microsoft-365-Teams','Identity- und Security-Verantwortliche','ERP-, CRM- und Prozessverantwortliche','Entwicklung und KI-Teams','Datenschutz und Compliance','IT-Einkauf und Lizenzmanagement'],['CIO, CTO and IT leadership','Cloud and enterprise architecture','Workplace and Microsoft 365 teams','Identity and security owners','ERP, CRM and process owners','Engineering and AI teams','Privacy and compliance','IT procurement and licensing'],[
('https://azure.microsoft.com/en-us/products/','Azure: Produktübersicht','Azure: product overview'),('https://www.microsoft.com/en-us/microsoft-365/microsoft-365-enterprise','Microsoft 365 für Unternehmen','Microsoft 365 for enterprises'),('https://www.microsoft.com/en-us/dynamics-365','Dynamics 365','Dynamics 365'),('https://www.microsoft.com/en-us/security','Microsoft Security, Entra und Purview','Microsoft Security, Entra and Purview')],['Microsoft Corporation'])
profile('NVIDIA','https://www.nvidia.com/en-us/data-center/','NVIDIA: Rechenzentrums- und KI-Plattform','NVIDIA: data-center and AI platform',
'NVIDIA entwickelt beschleunigte Rechenplattformen aus GPUs, CPUs, Netzwerktechnik und Software für KI, HPC, Datenanalyse und Visualisierung. DGX- und HGX-Plattformen sowie GPU- und Interconnect-Technologien adressieren Rechenzentren; Omniverse unterstützt Simulation und digitale Zwillinge, Edge-Angebote die Verarbeitung nahe am Einsatzort. Partner verbinden diese Bausteine mit Servern, Datenplattformen, Cloud-Betrieb und branchenspezifischen Anwendungen. Die Verknüpfungen zu HPE, Akamai, VAST Data, Reply oder NavVis beschreiben deshalb unterschiedliche Rollen im Gesamtsystem. Käufer sollten Workload, Speicher, Netzwerk, Energieversorgung, Kühlung, Softwarelizenzen und Support gemeinsam bewerten. Bei Inferenz zählen Antwortlatenz, Durchsatz und verfügbare Kapazität am benötigten Standort. Ankündigungen künftiger Plattformen, Referenzarchitekturen und produktiv verfügbare Konfigurationen bleiben voneinander getrennt.',
'NVIDIA develops accelerated computing platforms combining GPUs, CPUs, networking and software for AI, HPC, analytics and visualization. DGX and HGX platforms, GPUs and interconnect technologies address data centers; Omniverse supports simulation and digital twins, while edge offerings process data near its point of use. Partners combine these components with servers, data platforms, cloud operations and industry applications. Links to HPE, Akamai, VAST Data, Reply or NavVis therefore describe distinct roles in the overall system. Buyers should assess workloads, memory, networking, power, cooling, software licenses and support together. Inference depends on response latency, throughput and available capacity at the required location. Future platform announcements, reference architectures and production-ready configurations remain distinct.',
['GPU- und CPU-beschleunigtes Computing','KI-Training und Inferenz','DGX und HGX','Interconnect und Netzwerktechnik','KI-Software und Modellbereitstellung','Omniverse und digitale Zwillinge','HPC und wissenschaftliches Rechnen','Edge-KI und Partnerinfrastruktur'],['GPU- and CPU-accelerated computing','AI training and inference','DGX and HGX','Interconnect and networking','AI software and model deployment','Omniverse and digital twins','HPC and scientific computing','Edge AI and partner infrastructure'],
['KI- und HPC-Infrastruktur','Cloud- und Plattformarchitektur','Rechenzentrumsbetrieb','KI- und MLOps-Teams','Simulation und Engineering','Forschung und Hochschul-IT','IT-Einkauf und Systemintegration','CIO und CTO'],['AI and HPC infrastructure','Cloud and platform architecture','Data-center operations','AI and MLOps teams','Simulation and engineering','Research and university IT','IT procurement and systems integration','CIO and CTO'],[('https://www.nvidia.com/en-us/data-center/','NVIDIA: Plattform und Partnerbereitstellung','NVIDIA: platform and partner delivery'),('https://www.nvidia.com/en-us/solutions/','NVIDIA: Einsatzfelder','NVIDIA: use cases')],['NVIDIA Corporation'])
profile('Google Cloud','https://cloud.google.com/products','Google Cloud: Produkte und Dienste','Google Cloud: products and services',
'Google Cloud stellt Infrastruktur, Datenplattformen, KI-Dienste und Werkzeuge für Anwendungen bereit. BigQuery unterstützt Datenanalyse und die Verbindung von Daten- und KI-Workflows. Die aktuell unter der früheren Vertex-AI-Adresse erreichbare Gemini-Plattform beschreibt Entwicklung, Bereitstellung, Evaluation und Governance von KI-Modellen und Agenten. Compute-, Speicher- und Kubernetes-Dienste bilden weitere Architekturebenen. Partner wie Fortinet ergänzen Sicherheitsfunktionen, Fivetran Datenintegration und Reply Umsetzung und Befähigung. Ihre Leistungen werden als eigene Angebote mit einem belegten Google-Cloud-Bezug verlinkt. Bei der Auswahl sind Datenstandorte, Identitäten, Kosten, Netzwerkanbindung, Betriebsmodell und Integrationsaufwand je Dienst zu prüfen. Eine Partnerauszeichnung gilt für die genannte Kategorie und das genannte Jahr; sie bestätigt keine beliebige technische Leistung. Historische Produktnamen in Artikeln bleiben nachvollziehbar.',
'Google Cloud provides infrastructure, data platforms, AI services and application tooling. BigQuery supports analytics and connected data and AI workflows. The Gemini platform currently reached through the former Vertex AI address describes development, deployment, evaluation and governance of AI models and agents. Compute, storage and Kubernetes services form additional architectural layers. Partners such as Fortinet add security, Fivetran data integration and Reply implementation and enablement. Their services remain separate offerings linked through documented Google Cloud relationships. Selection requires service-specific assessment of data locations, identities, costs, connectivity, operating models and integration effort. A partner award applies to its stated category and year rather than certifying every technical service. Historical product names in articles remain traceable.',
['Cloud-Infrastruktur und Anwendungen','BigQuery und Datenanalyse','KI-Modelle und Gemini-Plattform','Kubernetes und Cloud-Betrieb','Datenintegration über Partner','Cloud-Sicherheit und Zugriffssteuerung','MLOps und Modellevaluation','Migration und Umsetzungspartner'],['Cloud infrastructure and applications','BigQuery and analytics','AI models and Gemini platform','Kubernetes and cloud operations','Partner data integration','Cloud security and access control','MLOps and model evaluation','Migration and implementation partners'],
['CIO und Cloud-Architektur','Data Engineering und Analytics','KI- und MLOps-Teams','Plattform- und Entwicklungsteams','CISO und Cloud-Security','FinOps und IT-Einkauf','Daten-Governance und Datenschutz','Migration und Systemintegration'],['CIO and cloud architecture','Data engineering and analytics','AI and MLOps teams','Platform and engineering teams','CISO and cloud security','FinOps and IT procurement','Data governance and privacy','Migration and systems integration'],[('https://cloud.google.com/products','Google Cloud: Produktportfolio','Google Cloud: product portfolio'),('https://cloud.google.com/bigquery','BigQuery','BigQuery'),('https://cloud.google.com/products/gemini-enterprise-agent-platform','Gemini-Plattform: aktuelle KI-Quelle','Gemini platform: current AI source')])
profile('SAP','https://www.sap.com/products.html','SAP: Unternehmenssoftware und Plattformen','SAP: enterprise software and platforms',
'SAP verbindet Unternehmensprozesse über ERP, Fachanwendungen, Daten und Integration. Cloud ERP adressiert Finanzen, Beschaffung und Lieferkette; die Business Technology Platform unterstützt Entwicklung, Automatisierung und Integration. Ergänzende Angebote umfassen Business AI, Business Data Cloud, Personalmanagement, Customer Experience und Geschäftsnetzwerke. SAP GROW, RISE with SAP und Business One stehen für unterschiedliche Einsatz- und Transformationskontexte. Im Ökosystem übernehmen Anbieter wie Natuvion, cbs, Sycor oder FIS Umsetzung und Erweiterung; Onapsis adressiert die Absicherung von SAP-Landschaften. Eine technische Integration oder Zertifizierung gilt jeweils für das bezeichnete Produkt. Sie ist keine pauschale Freigabe des gesamten Partnerportfolios. Käufer sollten Ausgangssysteme, Zielarchitektur, Datenmigration, Erweiterungen, Betriebsverantwortung und Lizenzfolgen gemeinsam prüfen. Die bestehenden SAP-Concur-Inhalte und andere Geschäftsbereiche behalten ihre eigene Identität und Quellenzuordnung.',
'SAP connects enterprise processes through ERP, business applications, data and integration. Cloud ERP addresses finance, procurement and supply chains; the Business Technology Platform supports development, automation and integration. Complementary offerings include Business AI, Business Data Cloud, HR, customer experience and business networks. SAP GROW, RISE with SAP and Business One serve different adoption and transformation contexts. Ecosystem companies such as Natuvion, cbs, Sycor or FIS deliver implementation and extensions; Onapsis addresses SAP landscape security. Technical integration or certification applies to the designated product rather than approving an entire partner portfolio. Buyers should assess source systems, target architecture, data migration, extensions, operational ownership and licensing implications together. Existing SAP Concur content and other business units retain their own identities and source attribution.',
['Cloud ERP und Unternehmensprozesse','SAP GROW und RISE with SAP','SAP Business One','Business Technology Platform','Business AI und Business Data Cloud','Integration und Prozessautomatisierung','Transformation und Partnererweiterungen','Absicherung von SAP-Landschaften'],['Cloud ERP and enterprise processes','SAP GROW and RISE with SAP','SAP Business One','Business Technology Platform','Business AI and Business Data Cloud','Integration and process automation','Transformation and partner extensions','SAP landscape security'],
['CIO und ERP-Verantwortliche','Finanzen und Controlling','Einkauf und Supply Chain','Daten- und Integrationsarchitektur','SAP-Basis und Betrieb','Informationssicherheit','Fachbereichsleitung und Transformation','IT-Einkauf und Lizenzmanagement'],['CIO and ERP owners','Finance and controlling','Procurement and supply chain','Data and integration architecture','SAP Basis and operations','Information security','Business leadership and transformation','IT procurement and licensing'],[('https://www.sap.com/products.html','SAP: Produktfamilien','SAP: product families'),('https://www.sap.com/products/erp.html','SAP Cloud ERP','SAP Cloud ERP')])
AWS='Amazon Web Services EMEA SARL, Niederlassung Deutschland'
profile(AWS,'https://aws.amazon.com/products/','AWS: Cloud-Produkte und Partnerökosystem','AWS: cloud products and partner ecosystem',
'Amazon Web Services bietet Cloud-Infrastruktur und Plattformdienste für Anwendungen, Daten und KI. Zum Portfolio gehören EC2 für Compute, S3 für Speicher, Datenbankdienste und Amazon Bedrock für generative KI und Agenten. Unternehmen beziehen Leistungen direkt oder ergänzen sie um Partnerprodukte, Implementierung und Betrieb. Reply adressiert Cloud-Transformation, Veeam Datensicherung in AWS-Umgebungen, Vodafone eine Cloud-Kooperation; Siemens-Inhalte behandeln die Nutzung von AWS-Infrastruktur für HPC. Diese Beziehungen bezeichnen unterschiedliche Angebote und Zuständigkeiten. Die vorhandene deutsche Niederlassungsbezeichnung bleibt als Katalogidentität erhalten und bedeutet keine ausschließliche lokale technische Verantwortung für globale AWS-Produkte. Für die Auswahl zählen Regionen, Datenhaltung, Konten- und Identitätsstruktur, Kosten, Resilienz und geteilte Sicherheitsverantwortung. Partnerstatus, Marketplace-Verfügbarkeit und technische Kompatibilität müssen jeweils anhand konkreter Quellen und Angebote geprüft werden.',
'Amazon Web Services provides cloud infrastructure and platform services for applications, data and AI. Its portfolio includes EC2 compute, S3 storage, databases and Amazon Bedrock for generative AI and agents. Businesses procure services directly or add partner products, implementation and operations. Reply addresses cloud transformation, Veeam backup in AWS environments, Vodafone a cloud collaboration, and Siemens content the use of AWS infrastructure for HPC. These relationships describe different offerings and responsibilities. The existing German branch designation remains the catalogue identity and does not imply exclusive local technical ownership of global AWS products. Selection depends on regions, data handling, account and identity structures, costs, resilience and shared security responsibility. Partner status, marketplace availability and technical compatibility require evidence for each specific source and offer.',
['EC2 und Cloud-Compute','S3 und Speicherdienste','Datenbanken und Datenplattformen','Amazon Bedrock und KI-Anwendungen','Hybrid-Cloud und Resilienz','Migration und Umsetzungspartner','Backup- und Integrationslösungen','Sicherheit und Kostenkontrolle'],['EC2 and cloud compute','S3 and storage services','Databases and data platforms','Amazon Bedrock and AI applications','Hybrid cloud and resilience','Migration and implementation partners','Backup and integration solutions','Security and cost control'],
['CIO und Cloud-Architektur','Plattform- und Entwicklungsteams','Daten- und KI-Verantwortliche','CISO und Cloud-Security','Backup und Business Continuity','Migration und IT-Betrieb','FinOps und IT-Einkauf','Datenschutz und Governance'],['CIO and cloud architecture','Platform and engineering teams','Data and AI owners','CISO and cloud security','Backup and business continuity','Migration and IT operations','FinOps and IT procurement','Privacy and governance'],[('https://aws.amazon.com/products/','AWS: Produktportfolio','AWS: product portfolio')],['AWS','Amazon Web Services'])
profile('Cisco','https://www.cisco.com/site/us/en/products/index.html','Cisco: Netzwerk-, Sicherheits- und Softwareportfolio','Cisco: networking, security and software portfolio',
'Cisco verbindet Unternehmensnetzwerke, Sicherheit, Rechenzentrumsinfrastruktur und Zusammenarbeit. Das Portfolio umfasst Switching, Wireless, WAN, Duo für Identität, Sicherheitslösungen und Observability; Splunk-Produkte werden in der Cisco-Produktübersicht ebenfalls geführt. Die Verknüpfung mit Splunk beschreibt einen Unternehmens- und Portfoliobezug und wird von Partnerintegrationen getrennt. Controlware bietet eigene Managed Services mit Cisco-Technologie; Tenable wird in einem konkreten Integrationsprogramm genannt. Die gemeinsame Meldung von Controlware, Cisco und Schwarz Digits behandelt ein Souveränitätsangebot, keine pauschale europäische Herkunft jedes Produktbausteins. Käufer sollten Netzarchitektur, Identitäten, Betriebsmodell, Lizenzierung, Telemetrie und Verantwortlichkeiten zwischen Netzwerk-, Sicherheits- und Anwendungsteams prüfen. Partner-Audits und Programmnennungen gelten nur für den belegten Umfang. Die bestehenden Anbieterprofile und Wissensobjekte behalten ihre Originalquellen.',
'Cisco combines enterprise networking, security, data-center infrastructure and collaboration. The portfolio includes switching, wireless, WAN, Duo identity security, other security offerings and observability; the Cisco product overview also lists Splunk products. The Splunk link describes a corporate and portfolio relationship, distinct from partner integrations. Controlware provides its own managed services using Cisco technology; Tenable is named in a specific integration program. The joint Controlware, Cisco and Schwarz Digits announcement concerns a sovereignty offering, not universal European origin for every component. Buyers should assess network architecture, identities, operating models, licensing, telemetry and responsibility across network, security and application teams. Partner audits and program references apply only to their documented scope. Existing provider profiles and knowledge items retain original sources.',
['Switching, Wireless und WAN','Netzwerk- und Zero-Trust-Sicherheit','Duo und Identitätskontrollen','Rechenzentrum und Computing','Zusammenarbeit und Webex','Splunk und Observability','Managed Services über Partner','Management und Integration'],['Switching, wireless and WAN','Network and Zero Trust security','Duo and identity controls','Data centers and computing','Collaboration and Webex','Splunk and observability','Partner managed services','Management and integration'],
['CIO und Netzwerkarchitektur','Netzwerk- und Rechenzentrumsbetrieb','CISO und Security Operations','Identity- und Access-Management','Observability und Anwendungsbetrieb','Collaboration-Verantwortliche','Systemintegration und Managed Services','IT-Einkauf und Lizenzmanagement'],['CIO and network architecture','Network and data-center operations','CISO and security operations','Identity and access management','Observability and application operations','Collaboration owners','Systems integration and managed services','IT procurement and licensing'],[('https://www.cisco.com/site/us/en/products/index.html','Cisco: Produkte einschließlich Splunk','Cisco: products including Splunk')])
