def edge(id,name,de_type,en_type,de,en,scope='Öffentliche Beschreibung'):
 r=edges.setdefault(id,dict(id=id,additionalProviders=[],providerRelations=[]))
 if name not in r['additionalProviders']:r['additionalProviders'].append(name)
 r['providerRelations'].append(dict(name=name,type=dict(de=de_type,en=en_type),context=dict(de=de,en=en),reviewedAt='2026-10-12',sourceUrl=items[id]['url'],scope=scope))
